 b=p.chromium.launch();g=b.new_page();g.goto('http://localhost:8080/');g.evaluate("async()=>{let m=await import('/fps-game.js');window.game=m.mountFPS(document.querySelector('#app'),{exercise:'front'})}");g.fill('#fpsSensitivity','2');g.locator('#fpsSensitivity').dispatch_event('input');g.click('#fpsStart');g.locator('#fpsCanvas').dispatch_event('mousemove',{'movementX':100,'movementY':0});assert abs(g.evaluate('game.state.yaw')-.46)<.01;g.evaluate('game.state.yaw=-.35');g.keyboard.press('Space');g.locator('#fpsCanvas').dispatch_event('mousedown',{'button':2});g.locator('#fpsCanvas').dispatch_event('mousedown',{'button':0});assert len(g.evaluate('game.state.entities[0].marks'))==1;assert g.evaluate('game.state.pitch')>.04 and g.evaluate('game.state.recoil')>1;g.keyboard.press('Escape');g.click('#fpsStart');g.evaluate('game.state.entities=[];game.state.yaw=0;game.state.x=8.5;game.state.y=8.5');g.keyboard.down('Shift');g.keyboard.down('w');g.wait_for_timeout(400);g.keyboard.up('w');g.keyboard.up('Shift');slow=g.evaluate('game.state.x')-8.5;g.keyboard.down('w');g.wait_for_timeout(400);g.keyboard.up('w');fast=g.evaluate('game.state.x')-8.5-slow;assert fast>slow*2;print('PASS persisted sensitivity, impact marks, strong recoil and Shift slow walk');b.close()
